  extend('cpp', 'basics', [
    { id: 'control', title: 'if, loops & switch', xp: 25, recap: 'Same <code>if</code>/<code>for</code>/<code>while</code> as JavaScript; <code>switch</code> works on ints and chars.', steps: [
      read('Familiar control flow', `${pre('int hp = 25;\nif (hp <= 0) {\n    std::cout << "Dead\\n";\n} else if (hp < 30) {\n    std::cout << "Low!\\n";\n}\n\nfor (int i = 0; i < 3; i++) {\n    std::cout << i << "\\n";\n}\n\nchar key = \'w\';\nswitch (key) {\n    case \'w\': y--; break;\n    case \'s\': y++; break;\n    default: break;\n}')}${tip('In C++, <code>\'w\'</code> (single quotes) is one <b>char</b>; <code>"w"</code> is a string.')}`),
      predict('int total = 0;\nfor (int i = 0; i < 5; i += 2) {\n    total += i;\n}\nstd::cout << total;', ['10', '6', '4', '9'], 1, '0 + 2 + 4 = 6'),
      code({ task: 'Write a <code>for</code> loop that counts down from 3 to 1 printing each number, then prints <b>Go!</b>', starter: '#include <iostream>\n\nint main() {\n    \n    return 0;\n}\n', hints: ['<code>for (int i = 3; i >= 1; i--)</code>'], solution: '#include <iostream>\n\nint main() {\n    for (int i = 3; i >= 1; i--) {\n        std::cout << i << "\\n";\n    }\n    std::cout << "Go!\\n";\n    return 0;\n}\n', check: R([[/for\s*\(\s*int\s+i\s*=\s*3\s*;\s*i\s*>=?\s*[01]\s*;\s*i--\s*\)/, 'Count down with <code>for (int i = 3; i >= 1; i--)</code>.'], [/std::cout\s*<<\s*i/, 'Print i inside the loop.'], [/std::cout\s*<<\s*"Go!/, 'Print Go! after the loop.']]) }),
      code({ task: 'Write a <code>switch</code> on <code>char key</code>: <code>\'a\'</code> sets <code>dx = -1</code>, <code>\'d\'</code> sets <code>dx = 1</code>, default sets <code>dx = 0</code>.', starter: 'char key = \'a\';\nint dx = 0;\n', hints: ['Each case ends with <code>break;</code>'], solution: 'char key = \'a\';\nint dx = 0;\nswitch (key) {\n    case \'a\': dx = -1; break;\n    case \'d\': dx = 1; break;\n    default: dx = 0; break;\n}\n', check: R([[/switch\s*\(\s*key\s*\)/, 'Use <code>switch (key)</code>.'], [/case\s*'a'\s*:\s*dx\s*=\s*-1\s*;\s*break\s*;/, 'Case <code>\'a\'</code>: <code>dx = -1; break;</code>'], [/case\s*'d'\s*:\s*dx\s*=\s*1\s*;\s*break\s*;/, 'Case <code>\'d\'</code>: <code>dx = 1; break;</code>'], [/default\s*:\s*dx\s*=\s*0/, 'Default: <code>dx = 0</code>.']]) }),
    ] },
    { id: 'strings', title: 'Strings & input', xp: 25, recap: '<code>std::string</code> joins with <code>+</code>, has <code>.size()</code>; <code>std::cin &gt;&gt; x</code> reads input.', steps: [
      read('Text in C++', `${pre('#include <string>\n\nstd::string name = "Aria";\nstd::string title = "Sir " + name;\nstd::cout << title.size();       // 8\n\nint age;\nstd::cin >> age;                 // read a number the user types')}`),
      quiz('What does <code>std::cin &gt;&gt; score;</code> do?', ['Prints score', 'Reads a value typed by the user into score', 'Deletes score', 'Compares score'], 1),
      code({ task: 'Read a player name with <code>std::cin</code> into <code>std::string name</code>, then print <b>Welcome, NAME!</b>', starter: '#include <iostream>\n#include <string>\n\nint main() {\n    \n    return 0;\n}\n', hints: ['<code>std::string name; std::cin >> name;</code>', '<code>std::cout << "Welcome, " << name << "!\\n";</code>'], solution: '#include <iostream>\n#include <string>\n\nint main() {\n    std::string name;\n    std::cin >> name;\n    std::cout << "Welcome, " << name << "!\\n";\n    return 0;\n}\n', check: R([[/std::string\s+name\s*;/, 'Declare <code>std::string name;</code>'], [/std::cin\s*>>\s*name\s*;/, 'Read it with <code>std::cin >> name;</code>'], [/std::cout\s*<<\s*"Welcome, "\s*<<\s*name\s*<<\s*"!/, 'Print <code>"Welcome, " << name << "!"</code>.']]) }),
    ] },
  ]);
  extend('cpp', 'vectors', [
    { id: 'structs', title: 'Structs & const references', xp: 35, recap: '<code>struct</code> groups data (public by default). Pass big things as <code>const T&amp;</code>: no copy, no changes.', steps: [
      read('Grouping data', `${pre('struct Vec2 {\n    float x = 0;\n    float y = 0;\n};\n\nstruct Enemy {\n    std::string name;\n    int hp;\n    Vec2 pos;\n};\n\nEnemy slime{"Slime", 10, {40, 80}};')}<p>A <code>struct</code> is like a class whose members are public by default — great for plain data.</p>`),
      read('const references', `<p>Passing a struct by value copies it. Use <code>const Enemy&amp;</code> to pass the original <b>read-only</b> — fast and safe:</p>${pre('void show(const Enemy& e) {\n    std::cout << e.name << " " << e.hp << "\\n";\n    // e.hp = 0;   // ✗ error: it’s const\n}')}`),
      quiz('Why use <code>const Enemy&amp;</code> as a parameter?', ['To copy the enemy', 'To avoid a copy and promise not to change it', 'To delete it after', 'It’s required for structs'], 1),
      code({ task: 'Declare <code>struct Item</code> with <code>std::string name</code> and <code>int price</code>, and write <code>int total(const std::vector&lt;Item&gt;&amp; items)</code> that adds up the prices.', starter: '#include <string>\n#include <vector>\n\n', hints: ['<code>for (const Item& it : items) sum += it.price;</code>'], solution: '#include <string>\n#include <vector>\n\nstruct Item {\n    std::string name;\n    int price;\n};\n\nint total(const std::vector<Item>& items) {\n    int sum = 0;\n    for (const Item& it : items) {\n        sum += it.price;\n    }\n    return sum;\n}\n', check: R([[/struct\s+Item\s*\{/, 'Declare <code>struct Item { … };</code>'], [/std::string\s+name\s*;/, 'Add <code>std::string name;</code>'], [/int\s+price\s*;/, 'Add <code>int price;</code>'], [/\}\s*;/, 'Structs end with <code>};</code>'], [/int\s+total\s*\(\s*const\s+std::vector\s*<\s*Item\s*>\s*&\s*items\s*\)/, 'Use <code>int total(const std::vector&lt;Item&gt;&amp; items)</code>.'], [/for\s*\(\s*(const\s+)?(Item|auto)\s*&?\s*\w+\s*:\s*items\s*\)/, 'Loop with a range-for over items.'], [/\+=\s*\w+\.price/, 'Add each price.'], [/return\s+\w+\s*;/, 'Return the sum.']]) }),
    ] },
  ]);
  extend('cpp', 'classes', [
    { id: 'inherit', title: 'Inheritance & virtual', xp: 40, recap: '<code>class Boss : public Enemy</code>; mark methods <code>virtual</code> and use <code>override</code> so the right version runs through a base pointer.', steps: [
      read('One list, many kinds', `<p>Games keep lists of “all enemies”, but each kind behaves differently. <code>virtual</code> makes C++ pick the right method at runtime:</p>${pre('class Enemy {\npublic:\n    virtual ~Enemy() = default;\n    virtual int damage() const { return 3; }\n};\n\nclass Boss : public Enemy {\npublic:\n    int damage() const override { return 15; }\n};\n\nstd::vector<std::unique_ptr<Enemy>> enemies;\nenemies.push_back(std::make_unique<Boss>());\nenemies[0]->damage();   // 15, thanks to virtual')}${tip('Give a base class a <code>virtual</code> destructor so child objects are cleaned up correctly.')}`),
      quiz('Without <code>virtual</code>, calling <code>damage()</code> through an <code>Enemy*</code> pointing at a Boss returns…', ['15', '3', 'An error', 'Random'], 1),
      code({ task: 'Write <code>class Archer : public Unit</code> that overrides <code>int range() const</code> to return 8.', starter: 'class Unit {\npublic:\n    virtual ~Unit() = default;\n    virtual int range() const { return 1; }\n};\n\n', hints: ['<code>int range() const override { return 8; }</code>', 'Remember <code>public:</code> and the closing <code>};</code>'], solution: 'class Unit {\npublic:\n    virtual ~Unit() = default;\n    virtual int range() const { return 1; }\n};\n\nclass Archer : public Unit {\npublic:\n    int range() const override { return 8; }\n};\n', check: R([[/class\s+Archer\s*:\s*public\s+Unit/, 'Declare <code>class Archer : public Unit</code>.'], [/int\s+range\s*\(\s*\)\s*const\s+override\s*\{\s*return\s+8\s*;\s*\}/, 'Override: <code>int range() const override { return 8; }</code>'], [/\}\s*;\s*$/, 'End the class with <code>};</code>']]) }),
    ] },
  ]);
