  extend('java', '$', [
    { id: 'commands', title: 'A plugin command', xp: 45, recap: 'Commands implement <code>CommandExecutor</code>: <code>onCommand</code> receives the sender and the arguments.', steps: [
      read('/heal', `<p>Plugins add chat commands. The class implements <code>CommandExecutor</code>, and the server calls <code>onCommand</code>:</p>${pre('public class HealCommand implements CommandExecutor {\n    @Override\n    public boolean onCommand(CommandSender sender, Command cmd, String label, String[] args) {\n        if (sender instanceof Player p) {\n            p.setHealth(20.0);\n            p.sendMessage("Healed!");\n        }\n        return true;\n    }\n}')}<p><code>instanceof Player p</code> checks the sender is a player (not the console) and names it <code>p</code>.</p>`),
      quiz('Why check <code>sender instanceof Player</code>?', ['Commands can also come from the server console', 'It makes it faster', 'It’s required syntax', 'To ban the player'], 0),
      code({ task: 'Write <code>FlyCommand implements CommandExecutor</code>: if the sender is a player, call <code>p.setAllowFlight(true)</code> and send <b>"You can fly!"</b>. Return true.', starter: '', hints: ['Copy the shape of HealCommand.'], solution: 'public class FlyCommand implements CommandExecutor {\n    @Override\n    public boolean onCommand(CommandSender sender, Command cmd, String label, String[] args) {\n        if (sender instanceof Player p) {\n            p.setAllowFlight(true);\n            p.sendMessage("You can fly!");\n        }\n        return true;\n    }\n}\n',
        check: R([[/class\s+FlyCommand\s+implements\s+CommandExecutor/, 'Declare <code>class FlyCommand implements CommandExecutor</code>.'], [/public\s+boolean\s+onCommand\s*\(\s*CommandSender\s+sender\s*,\s*Command\s+\w+\s*,\s*String\s+\w+\s*,\s*String\s*\[\s*\]\s*\w+\s*\)/, 'Add the <code>onCommand(CommandSender sender, Command cmd, String label, String[] args)</code> method.'], [/sender\s+instanceof\s+Player\s+\w+/, 'Check <code>sender instanceof Player p</code>.'], [/\w+\.setAllowFlight\s*\(\s*true\s*\)/, 'Call <code>p.setAllowFlight(true)</code>.'], [/\w+\.sendMessage\s*\(\s*"You can fly!"\s*\)/, 'Send "You can fly!".'], [/return\s+true/, 'Return true.']]) }),
      code({ task: 'Use <code>args</code>: if <code>args.length &gt; 0</code> and <code>args[0].equals("off")</code>, call <code>setAllowFlight(false)</code> and send <b>"Flight off"</b> instead.', keep: true, hints: ['Check args inside the player block, before turning flight on.'], solution: 'public class FlyCommand implements CommandExecutor {\n    @Override\n    public boolean onCommand(CommandSender sender, Command cmd, String label, String[] args) {\n        if (sender instanceof Player p) {\n            if (args.length > 0 && args[0].equals("off")) {\n                p.setAllowFlight(false);\n                p.sendMessage("Flight off");\n            } else {\n                p.setAllowFlight(true);\n                p.sendMessage("You can fly!");\n            }\n        }\n        return true;\n    }\n}\n',
        check: R([[/args\.length\s*>\s*0\s*&&\s*args\s*\[\s*0\s*\]\.equals\s*\(\s*"off"\s*\)/, 'Check <code>args.length > 0 && args[0].equals("off")</code>.'], [/setAllowFlight\s*\(\s*false\s*\)/, 'Turn flight off with <code>setAllowFlight(false)</code>.'], [/sendMessage\s*\(\s*"Flight off"\s*\)/, 'Send "Flight off".'], [/setAllowFlight\s*\(\s*true\s*\)/, 'Keep the normal fly-on case.']]), success: 'Register it in your plugin.yml and you have a working /fly command.' }),
    ] },
  ]);
